            var lib = loadLibWithGlobals({
                confluence_get_page_inline_comments: function() { return raw; }
            });
            var comments = lib.fetchPageInlineComments('1', 'T');
            assert.equal(comments.length, 1);
            assert.equal(comments[0].resolved, pair[1]);
        });
    });

