                storage: { value: 'S' },
                atlas_doc_format: { value: 'A' },
                view: { value: 'V' }
            } }),
            'S'
        );
        assert.equal(
            lib.extractCommentBody({ body: { atlas_doc_format: { value: 'A' }, view: { value: 'V' } } }),
