        var lib = loadLib();
        assert.equal(
            lib.extractCommentBody({ body: {
                storage: { value: 'S' },
                atlas_doc_format: { value: 'A' },
                view: { value: 'V' }
            } }),
            'S'
        );
        assert.equal(
            lib.extractCommentBody({ body: { atlas_doc_format: { value: 'A' }, view: { value: 'V' } } }),
            'A'
        );
    });

    test('skips representations whose value is not a string', function() {
        var lib = loadLib();
