/**
 * Parse an AI JSON string response. Returns { value } on success or
 * { error } when the payload is not valid JSON (the original error is kept
 * for the caller's log, preserving the pre-extraction message and flow).
 */
function parseAiJson(text) {
   try {
       return { value: JSON.parse(text) };
   } catch (error) {
       return { error: error };
   }

function parseModuleAnalysisResponse(response) {
   // Handle string responses (parse JSON)
   if (typeof response === 'string') {
       var parsed = parseAiJson(response);
       if (parsed.error) {
           console.error('Invalid JSON from AI:', parsed.error);
           return null;
       }
       response = parsed.value;
