        getTracker().postComment(ticketKey, '*Error:* ' + errorMsg + '. Please check logs for details and retry the workflow.');
    } catch (commentError) {
        console.error('Failed to post error comment:', commentError);
    }

    return {
        success: false,
        error: errorMsg
    };
}

/**
