function stats(file) {
  const lines = fs.readFileSync(file, 'utf8').split('\n');
  let max = 0, over = 0, rows = 0;
  for (const l of lines) {
    const m = l.match(/^(\S+)\s+(\S+)\s+(\d+)\s+([\d.]+%|N\/A)\s+([\d.]+|N\/A)\s*$/);
    if (!m) continue;
    rows++;
    if (m[5] === 'N/A') continue;
    const crap = parseFloat(m[5]);
    if (crap > max) max = crap;
    if (crap > 8) over++;
  }
  return { rows, max, over };
}
