function resolveTrackerType(config, options) {
    var trackerType = null;
    try {
        trackerType = java.lang.System.getenv('DEFAULT_TRACKER');
    } catch (e) {
        // Not running in GraalJS environment
    }
    if (!trackerType && config.defaultTracker) {
